impl RunCfg<'_> {
    /// CPU id for the bench's `thread_idx`-th thread, using
    /// wrap-around over the pool. Returns `None` when the pool is
    /// empty so callers can treat unpinned and pinned runs uniformly.
    pub fn cpu_for(&self, thread_idx: usize) -> Option<usize> {
        if self.pin_cpus.is_empty() {
            None
        } else {
            Some(self.pin_cpus[thread_idx % self.pin_cpus.len()])
        }
    }
}

/// Per-block statistics of a run. With a nonzero
/// block sleep each block is a mini-run (own sleep re-roll +
/// warm-up), so the spread of block means yields an
/// honest-per-invocation CI and LSC. With no sleep the blocks are
/// partitions of one continuous run — they share the run's state,
/// cannot replicate it, and CI95 / LSC are withheld rather than
/// printed as a fiction. See
/// notes/design.md#within-invocation-replication-sleep-separated-blocks.
#[derive(Debug)]
pub struct BlockStats {
    /// Number of blocks (Y).
    pub blocks: u64,
    /// Sample-count weighted mean of the per-block means, ns: the
    /// exact mean of every sample, the report's `mean` and the
    /// record's `mean_ns`. With equal counts it is their plain
    /// average, and a block the time cap cut keeps its weight.
    pub mean_ns: f64,
    /// 95% confidence half-width on `mean_ns`:
    /// `t(0.975, Y-1) * s / sqrt(Y)`, ns. `None` when the blocks
    /// are sleepless partitions rather than replicates, or fewer
    /// than [`crate::gauge::MIN_SERIES_POINTS`].
    pub ci95_ns: Option<f64>,
    /// Least significant change vs an equal-Y run of another
    /// implementation: `t(0.975, 2Y-2) * s * sqrt(2/Y)`, ns.
    /// `None` when the blocks are sleepless partitions, or fewer
    /// than [`crate::gauge::MIN_SERIES_POINTS`].
    pub lsc_ns: Option<f64>,
}

impl BlockStats {
    /// Fit from the block summaries' exact means. CI95 and LSC
    /// treat each block mean as one equal replicate, exact with
    /// equal counts and an approximation when the time cap cut
    /// some blocks short, which the report says.
    /// `replicated` says whether a nonzero sleep separated the
    /// blocks; without one the t-formulas' independence premise is
    /// false, so CI95 / LSC stay `None`. They also stay `None`
    /// below [`crate::gauge::MIN_SERIES_POINTS`] blocks, where the
    /// t multiplier is far from its limit (12.7 at one degree of
    /// freedom, near flat from eight on), the same floor the
    /// gauge's series signals withhold under. Caller guarantees
    /// `blocks` is non-empty.
    fn from_blocks(blocks: &[BlockSummary], replicated: bool) -> BlockStats {
        let means: Vec<f64> = blocks.iter().map(|b| b.mean_ps / PS_PER_NS).collect();
        let y = means.len() as f64;
        let yy = means.len() as u64;
        let total: u64 = blocks.iter().map(|b| b.count).sum();
        let mean = if total > 0 {
            blocks
                .iter()
                .map(|b| b.mean_ps / PS_PER_NS * b.count as f64)
                .sum::<f64>()
                / total as f64
        } else {
            means.iter().sum::<f64>() / y
        };
        let (ci95_ns, lsc_ns) = if replicated && means.len() >= crate::gauge::MIN_SERIES_POINTS {
            let replicate_mean = means.iter().sum::<f64>() / y;
            let var = means
                .iter()
                .map(|m| (m - replicate_mean) * (m - replicate_mean))
                .sum::<f64>()
                / (y - 1.0);
            let s = var.sqrt();
            (
                Some(t975(yy - 1) * s / y.sqrt()),
                Some(t975(2 * yy - 2) * s * (2.0 / y).sqrt()),
            )
        } else {
            (None, None)
        };
        BlockStats {
            blocks: yy,
            mean_ns: mean,
            ci95_ns,
            lsc_ns,
        }
    }
}

/// Two-sided 95% Student-t quantile (`t(0.975, df)`), table for
/// df ≤ 30, then the conservative 2.0 (the true value falls from
/// 2.042 toward the normal 1.96). Shared with
/// [`crate::resolution`], which applies the same LSC formula per
/// aggregation level.
pub(crate) fn t975(df: u64) -> f64 {
    const TABLE: [f64; 30] = [
        12.706, 4.303, 3.182, 2.776, 2.571, 2.447, 2.365, 2.306, 2.262, 2.228, 2.201, 2.179, 2.160,
        2.145, 2.131, 2.120, 2.110, 2.101, 2.093, 2.086, 2.080, 2.074, 2.069, 2.064, 2.060, 2.056,
        2.052, 2.048, 2.045, 2.042,
    ];
    match df {
        0 => f64::INFINITY,
        1..=30 => TABLE[(df - 1) as usize],
        _ => 2.0,
    }
}

