1	//! The run's honest resolution: a variance-versus-aggregation
2	//! curve over block means, whose plateau is the drift floor.
3	//!
4	//! The block LSC treats block means as independent draws, but
5	//! blocks milliseconds apart share the run's thermal and P-state
6	//! history, so it read ~7x optimistic against measured run-to-run
7	//! scatter. A single run cannot measure run-to-run scatter
8	//! directly; what it can do is watch whether variance falls as
9	//! `1/n` under aggregation (Allan deviation's move, IEEE Std
10	//! 1139). Where it stops falling is drift the run cannot average
11	//! away, and that floor is the smallest delta the run can
12	//! honestly claim to resolve.
13	//!
14	//! - The curve is fit on **block means**: contiguous slices of
15	//!   one sample count, the shape Allan deviation is defined over,
16	//!   present in every run since every run is blocks.
17	//! - Group means are sample-count weighted: with equal block
18	//!   counts that is the plain mean, and it stays right should a
19	//!   block ever come out short.
20	//! - Each level applies the LSC formula to its groups
21	//!   (`t(0.975, 2J-2) * s * sqrt(2/J)`), and the floor is the
22	//!   worst level: under white noise the levels agree, under drift
23	//!   the deeper levels rise, and taking the max cannot understate.
24	//! - Levels below [`MIN_GROUPS`] groups are excluded (the first
25	//!   level excepted): at J=2 the t multiplier alone inflates the
26	//!   claim 2.2x, so a deeper level would report its own
27	//!   uncertainty as drift.
28	
29	use crate::harness::{BlockSummary, PS_PER_NS};
30	use crate::series::{Series, weighted_mean};
31	
32	/// Minimum groups for an aggregation level past the first:
33	/// t(2J-2)*sqrt(2/J) is within ~9% of its limit at J=8 and 2.2x
34	/// at J=2, so deeper levels would be dominated by their own
35	/// estimator noise rather than by drift.
36	pub(crate) const MIN_GROUPS: u64 = 8;
37	
38	/// One aggregation level of the curve.
39	#[derive(Debug, Clone, Copy)]
40	pub struct CurvePoint {
41	    /// Blocks per group at this level (1, 2, 4, ...).
42	    pub group: u64,
43	    /// Groups the level yielded (trailing remainder dropped).
44	    pub groups: u64,
45	    /// The LSC formula applied to this level's group means, ns.
46	    pub res_ns: f64,
47	}
48	
49	/// The fitted curve and its floor: the run's resolution claim.
50	#[derive(Debug)]
51	pub struct Resolution {
52	    /// The claim: the worst level's `res_ns`.
53	    pub floor_ns: f64,
54	    /// Blocks per group at the floor level.
55	    pub floor_group: u64,
56	    /// Groups at the floor level.
57	    pub floor_groups: u64,
58	    /// Every level fitted, shallow to deep.
59	    #[allow(dead_code)]
60	    // OK: the fitted levels behind the floor, asserted by this
61	    // module's tests and reproducible from the record's block
62	    // series; a -v curve display is the intended future reader.
63	    pub curve: Vec<CurvePoint>,
64	}
65	
66	/// Fit the curve from a run's block series. `None` below two
67	/// usable blocks: one slice supports no variance at all.
68	pub fn from_blocks(blocks: &[BlockSummary]) -> Option<Resolution> {
69	    let usable: Vec<&BlockSummary> = blocks.iter().filter(|b| b.count > 0).collect();
70	    let b = usable.len() as u64;
71	    if b < 2 {
72	        return None;
73	    }
74	    let mut curve = Vec::new();
75	    let mut group = 1u64;
76	    while (group == 1 && b >= 2) || b / group >= MIN_GROUPS {
77	        if let Some(point) = level(&usable, group) {
78	            curve.push(point);
79	        }
80	        group *= 2;
81	        if b / group < 2 {
82	            break;
83	        }
84	    }
85	    #[allow(clippy::unwrap_used)]
86	    // OK: the b >= 2 guard above put at least the group=1 level in the curve
87	    let floor = curve
88	        .iter()
89	        .copied()
90	        .max_by(|a, c| a.res_ns.total_cmp(&c.res_ns))
91	        .unwrap();
92	    Some(Resolution {
93	        floor_ns: floor.res_ns,
94	        floor_group: floor.group,
95	        floor_groups: floor.groups,
96	        curve,
97	    })
98	}
99	
100	/// Fit one level: chunk the series into groups of `group`
101	/// consecutive blocks (remainder dropped), take count-weighted
102	/// group means, and apply the LSC formula to their spread.
103	/// `None` when the level yields fewer than two groups.
104	fn level(blocks: &[&BlockSummary], group: u64) -> Option<CurvePoint> {
105	    let means: Vec<f64> = blocks
106	        .chunks_exact(group as usize)
107	        .map(|chunk| {
108	            let points: Vec<(f64, u64)> = chunk
109	                .iter()
110	                .map(|x| (x.mean_ps / PS_PER_NS, x.count))
111	                .collect();
112	            weighted_mean(&points)
113	        })
114	        .collect();
115	    let s = Series::of(&means)?;
116	    Some(CurvePoint {
117	        group,
118	        groups: s.n,
119	        res_ns: s.lsc(),
120	    })
121	}
122	
