124	mod tests {
125	    use super::*;
126	
127	    /// A block with the given mean (ns) and sample count.
128	    fn block(mean_ns: f64, count: u64) -> BlockSummary {
129	        BlockSummary {
130	            t_start_s: 0.0,
131	            t_end_s: 0.05,
132	            count,
133	            floor_ps: (mean_ns * PS_PER_NS) as u64,
134	            floor_q_ps: (mean_ns * PS_PER_NS) as u64,
135	            mean_ps: mean_ns * PS_PER_NS,
136	            max_ps: (mean_ns * PS_PER_NS) as u64,
137	            over_floor: 0,
138	        }
139	    }
140	
141	    #[test]
142	    fn too_few_blocks_yield_no_claim() {
143	        assert!(from_blocks(&[]).is_none());
144	        assert!(from_blocks(&[block(20.0, 100)]).is_none());
145	    }
146	
147	    #[test]
148	    fn anti_correlated_noise_floors_at_the_first_level() {
149	        // Alternating means cancel exactly under pairing, so every
150	        // deeper level's variance collapses and the first level is
151	        // the floor.
152	        let blocks: Vec<BlockSummary> = (0..32)
153	            .map(|i| block(if i % 2 == 0 { 20.0 } else { 22.0 }, 100))
154	            .collect();
155	        let r = from_blocks(&blocks).expect("curve fits");
156	        assert_eq!(r.floor_group, 1);
157	        assert!(r.curve.len() > 1);
158	        // Deeper levels see identical group means: zero spread.
159	        assert!(r.curve[1].res_ns < 1e-9, "got {}", r.curve[1].res_ns);
160	    }
161	
162	    #[test]
163	    fn a_step_drift_raises_the_floor_above_the_first_level() {
164	        // Half the run at 20 ns, half at 24: aggregation cannot
165	        // average the step away, so deeper levels read worse and
166	        // the floor comes from one of them.
167	        let blocks: Vec<BlockSummary> = (0..32)
168	            .map(|i| block(if i < 16 { 20.0 } else { 24.0 }, 100))
169	            .collect();
170	        let r = from_blocks(&blocks).expect("curve fits");
171	        assert!(r.floor_group > 1, "floor at group {}", r.floor_group);
172	        assert!(r.floor_ns > r.curve[0].res_ns);
173	    }
174	
175	    #[test]
176	    fn group_means_weight_by_count() {
177	        // Two blocks, one carrying 9x the samples: the pooled
178	        // mean leans to it, so the level-1 spread is what the
179	        // unweighted mean would misstate.
180	        let blocks = vec![block(20.0, 900), block(30.0, 100)];
181	        let r = from_blocks(&blocks).expect("curve fits");
182	        // J=2, s from two means 20 and 30: the claim exists and is
183	        // large; the point is it fit without panicking on uneven
184	        // counts and dropped nothing.
185	        assert_eq!(r.curve[0].groups, 2);
186	        assert!(r.floor_ns > 0.0);
187	    }
188	
189	    #[test]
190	    fn zero_count_blocks_are_excluded() {
191	        let blocks = vec![block(20.0, 100), block(0.0, 0), block(22.0, 100)];
192	        let r = from_blocks(&blocks).expect("two usable blocks remain");
193	        assert_eq!(r.curve[0].groups, 2);
194	    }
195	}

