// Layered defaults (built-in < XDG file < project-local file <
// CLI). A malformed config is fatal so a typo surfaces.
let (config, config_files) = match config::load() {
    Ok(c) => c,
    Err(e) => {
        eprintln!("error: config: {e}");
        std::process::exit(2);
    }
};

