728	/// Cap on recorded block-series points: past it adjacent blocks merge, so a record never
729	/// grows unbounded with `--blocks` and the resolution curve stays reproducible for group sizes
730	/// at or above the recorded aggregation.
731	const MAX_BLOCK_POINTS: usize = 1000;
732	
733	/// The record's block-mean series: per-point mean (ns) and sample count, plus how many
734	/// blocks each point aggregates (1 = verbatim, powers of 2 past the cap). Zero-count blocks
735	/// are dropped, exactly as [`crate::resolution::from_blocks`] drops them.
736	fn block_series(blocks: &[BlockSummary]) -> (Vec<f64>, Vec<u64>, u64) {
737	    let usable: Vec<&BlockSummary> = blocks.iter().filter(|b| b.count > 0).collect();
738	    let mut agg: usize = 1;
739	    while usable.len().div_ceil(agg) > MAX_BLOCK_POINTS {
740	        agg *= 2;
741	    }
742	    let mut means = Vec::with_capacity(usable.len().div_ceil(agg));
743	    let mut counts = Vec::with_capacity(means.capacity());
744	    for chunk in usable.chunks(agg) {
745	        let count: u64 = chunk.iter().map(|b| b.count).sum();
746	        let sum: f64 = chunk.iter().map(|b| b.mean_ps * b.count as f64).sum();
747	        means.push(sum / count as f64 / PS_PER_NS);
748	        counts.push(count);
749	    }
750	    (means, counts, agg as u64)
