1	//! One bench per process: the parent's spawn of a child and the child's side of it.
2	//!
3	//! A process start re-rolls where a bench's rings and stacks land in memory, and that placement
4	//! sets the bench's level, so a bench sharing a process with the benches before it inherits their
5	//! placement. Every bench runs in a child of its own instead.
6	//!
7	//! - The parent resolves every run knob once, starts the sleep inhibit and the clock pin once,
8	//!   and for each bench writes a [`Spec`] to a file and runs `current_exe()` with the hidden
9	//!   `--child-spec PATH`. It waits in the kernel while the child measures, so it adds no thread of
10	//!   its own to the run, the `suggest-freq` sampler bug in notes/bugs.md being the warning.
11	//! - The child reads the spec, pins its main thread to the pool's first CPU, calibrates the tick
12	//!   rate, runs the one bench, and prints only that bench's report, the parent having printed the
13	//!   banner, `Setup:`, and `Config:`.
14	//! - A spec carries resolved values, never flags, so a child loads no config file, and the
15	//!   record's `config` is the parent's, the one the report printed.
16	
17	use std::path::{Path, PathBuf};
18	use std::process::Command;
19	
20	use clap::ValueEnum;
21	use serde::{Deserialize, Serialize};
22	
23	use crate::bands::BandLabels;
24	use crate::harness::RunCfg;
25	use crate::record::{RecordConfig, Recorder};
26	
27	/// Everything a child needs to run one bench as the parent resolved it.
28	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
29	pub struct Spec {
30	    /// The registered bench name, exact.
31	    pub bench: String,
32	    /// [`RunCfg::target_seconds`].
33	    pub target_seconds: f64,
34	    /// [`RunCfg::samples_override`].
35	    pub samples_override: Option<u64>,
36	    /// [`RunCfg::inner_override`].
37	    pub inner_override: Option<u64>,
38	    /// [`RunCfg::pin_cpus`], resolved from any profile name.
39	    pub pin_cpus: Vec<usize>,
40	    /// [`RunCfg::report_ticks`].
41	    pub report_ticks: bool,
42	    /// [`RunCfg::seam_probes`].
43	    pub seam_probes: bool,
44	    /// [`RunCfg::band_labels`], as its lowercase name.
45	    pub band_labels: String,
46	    /// [`RunCfg::decimals`].
47	    pub decimals: usize,
48	    /// [`RunCfg::settle_time_s`]. Every child is a fresh process, so every child pays it.
49	    pub settle_time_s: f64,
50	    /// [`RunCfg::warm_cap_s`].
51	    pub warm_cap_s: f64,
52	    /// [`RunCfg::blocks`].
53	    pub blocks: u64,
54	    /// [`RunCfg::block_sleep_s`].
55	    pub block_sleep_s: (f64, f64),
56	    /// [`RunCfg::block_warmup_s`].
57	    pub block_warmup_s: f64,
58	    /// Where and how the child records, when `--record` was given.
59	    pub record: Option<RecordSpec>,
60	}
61	
62	/// The `--record` sink as a child rebuilds it: the path made absolute, the tags verbatim, and
63	/// the parent's resolved config.
64	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
65	pub struct RecordSpec {
66	    /// The `--record` path, absolute.
67	    pub path: PathBuf,
68	    /// The `--tag` list, verbatim.
69	    pub tags: Vec<String>,
70	    /// The run's config as the parent's `Config:` list resolved it.
71	    pub config: RecordConfig,
72	}
73	
74	impl Spec {
75	    /// The spec for running `bench` under `cfg`, recording through `record` when set.
76	    pub fn new(bench: &str, cfg: &RunCfg, record: Option<RecordSpec>) -> Spec {
77	        Spec {
78	            bench: bench.to_string(),
79	            target_seconds: cfg.target_seconds,
80	            samples_override: cfg.samples_override,
81	            inner_override: cfg.inner_override,
82	            pin_cpus: cfg.pin_cpus.to_vec(),
83	            report_ticks: cfg.report_ticks,
84	            seam_probes: cfg.seam_probes,
85	            band_labels: cfg.band_labels.as_str().to_string(),
86	            decimals: cfg.decimals,
87	            settle_time_s: cfg.settle_time_s,
88	            warm_cap_s: cfg.warm_cap_s,
89	            blocks: cfg.blocks,
90	            block_sleep_s: cfg.block_sleep_s,
91	            block_warmup_s: cfg.block_warmup_s,
92	            record,
93	        }
94	    }
95	}
96	
97	/// A private directory for one invocation's spec files, under the system temp directory and
98	/// named by the parent's pid, removed by [`ScratchDir`]'s drop.
99	pub struct ScratchDir(PathBuf);
100	
101	impl ScratchDir {
102	    /// Create the directory.
103	    pub fn new() -> Result<ScratchDir, String> {
104	        let dir = std::env::temp_dir().join(format!("{}-{}", crate::BIN_NAME, std::process::id()));
105	        std::fs::create_dir_all(&dir).map_err(|e| format!("creating {}: {e}", dir.display()))?;
106	        Ok(ScratchDir(dir))
107	    }
108	
109	    /// The directory's path.
110	    pub fn path(&self) -> &Path {
111	        &self.0
112	    }
113	}
114	
115	impl Drop for ScratchDir {
116	    /// Remove the directory and whatever a child left in it. A failure leaves a small directory
117	    /// in the temp area, which is not worth failing a finished run over.
118	    fn drop(&mut self) {
119	        if let Err(e) = std::fs::remove_dir_all(&self.0) {
120	            log::warn!("removing {}: {e}", self.0.display());
121	        }
122	    }
123	}
124	
125	/// Run `spec` in a child of `exe`, its spec file named by `index` inside `dir`, waiting for it
126	/// to exit. The child inherits stdout and stderr, so its report streams as it prints. `verbose`
127	/// passes `-v` on.
128	pub fn spawn(
129	    exe: &Path,
130	    dir: &Path,
131	    index: usize,
132	    spec: &Spec,
133	    verbose: bool,
134	) -> Result<(), String> {
135	    let path = dir.join(format!("child-{index}.json"));
136	    let text = serde_json::to_string(spec).map_err(|e| format!("serializing the spec: {e}"))?;
137	    std::fs::write(&path, text).map_err(|e| format!("writing {}: {e}", path.display()))?;
138	    let mut cmd = Command::new(exe);
139	    cmd.arg("--child-spec").arg(&path);
140	    if verbose {
141	        cmd.arg("-v");
142	    }
143	    let status = cmd
144	        .status()
145	        .map_err(|e| format!("{}: spawning {}: {e}", spec.bench, exe.display()))?;
146	    if status.success() {
147	        Ok(())
148	    } else {
149	        Err(format!("{}: the child process {status}", spec.bench))
150	    }
151	}
152	
153	/// The child's side: read the spec at `spec_path`, run its bench, and return the exit code.
154	pub fn child_main(spec_path: &Path) -> i32 {
155	    match run_spec(spec_path) {
156	        Ok(()) => 0,
157	        Err(e) => {
158	            eprintln!("error: child: {e}");
159	            2
160	        }
161	    }
162	}
163	
164	/// Read, check, and run one spec: pin main to the pool's first CPU, warm the tick-rate
165	/// calibration before anything measures, build the record sink, and run the bench.
166	fn run_spec(spec_path: &Path) -> Result<(), String> {
167	    let text = std::fs::read_to_string(spec_path)
168	        .map_err(|e| format!("reading {}: {e}", spec_path.display()))?;
169	    let spec: Spec =
170	        serde_json::from_str(&text).map_err(|e| format!("parsing {}: {e}", spec_path.display()))?;
171	    let run = crate::benches::find(&spec.bench)
172	        .ok_or_else(|| format!("no bench is named '{}'", spec.bench))?;
173	    let band_labels =
174	        BandLabels::from_str(&spec.band_labels, false).map_err(|e| format!("band_labels: {e}"))?;
175	    if let Some(&cpu) = spec.pin_cpus.first() {
176	        crate::pin::pin_current(Some(cpu));
177	    }
178	    crate::ticks::ticks_per_ns();
179	    let recorder = match &spec.record {
180	        None => None,
181	        Some(r) => Some(Recorder::new(&r.path, &r.tags, r.config.clone())?),
182	    };
183	    let cfg = RunCfg {
184	        target_seconds: spec.target_seconds,
185	        samples_override: spec.samples_override,
186	        inner_override: spec.inner_override,
187	        pin_cpus: &spec.pin_cpus,
188	        report_ticks: spec.report_ticks,
189	        seam_probes: spec.seam_probes,
190	        band_labels,
191	        decimals: spec.decimals,
192	        settle_time_s: spec.settle_time_s,
