1	//! Replication across processes: each bench runs `runs` times back to back, every run a fresh
2	//! child, and the bench's mean, stdev, CI95, and LSC come from the runs' means.
3	//!
4	//! Blocks inside one process share the placement the process drew, so their CI95 and LSC are
5	//! lower bounds on the spread a fresh process shows. A run is one process, and a series of run
6	//! means is the first replicate that re-rolls placement, so its error bars are the first that are
7	//! not lower bounds ([`crate::series`] owns the arithmetic).
8	//!
9	//! - A bench's runs go back to back, not interleaved with another bench's (wink, at the cycle's
10	//!   opening): a bench is compared by its own error bars, and a drift of the host between two
11	//!   benches' runs is a bias neither bench's CI95 contains.
12	//! - A run sleep, a time or a random range, goes before every run after the invocation's first.
13	//! - One run prints the child's report as a single process did. Several runs print a line per
14	//!   run as each child finishes, then the bench's summary, and `-v` shows every child's report
15	//!   as well.
16	
17	use std::path::Path;
18	
19	use crate::child::{self, RecordSpec, Spec};
20	use crate::dither::Dither;
21	use crate::harness::RunCfg;
22	use crate::record::{self, RunSummary};
23	use crate::report::{fmt_claim, fmt_commas_f64, print_summary_rows};
24	use crate::series::Series;
25	
26	/// How an invocation's runs are spawned and shown.
27	pub struct Plan<'a> {
28	    /// The binary each child runs.
29	    pub exe: &'a Path,
30	    /// The invocation's scratch directory, for spec and result files.
31	    pub scratch: &'a Path,
32	    /// Runs per bench, one or more.
33	    pub runs: u64,
34	    /// The sleep before every run after the first, `(min_s, max_s)` seconds.
35	    pub run_sleep_s: (f64, f64),
36	    /// Pass `-v` to the children and show their reports beside the run lines.
37	    pub verbose: bool,
38	    /// Decimal digits on the time columns, the report's `--decimals`.
39	    pub decimals: usize,
40	}
41	
42	/// Spawns the runs of an invocation's benches in order, carrying the run count across benches
43	/// so the sleep and the scratch file names span the whole invocation.
44	pub struct Runner<'a> {
45	    /// The invocation's plan.
46	    plan: Plan<'a>,
47	    /// Draws the run sleeps.
48	    dither: Dither,
49	    /// Runs spawned so far in this invocation.
50	    spawned: u64,
51	}
52	
53	impl<'a> Runner<'a> {
54	    /// A runner for `plan`, nothing spawned yet.
55	    pub fn new(plan: Plan<'a>) -> Runner<'a> {
56	        Runner {
57	            plan,
58	            dither: Dither::new(),
59	            spawned: 0,
60	        }
61	    }
62	
63	    /// Run `bench` `runs` times under `cfg`, each run a fresh child recording with `record`, and
64	    /// print its runs and summary when there are several.
65	    pub fn bench(&mut self, bench: &str, cfg: &RunCfg, record: &RecordSpec) -> Result<(), String> {
66	        let several = self.plan.runs > 1;
67	        let show_report = !several || self.plan.verbose;
68	        if several {
69	            println!("{bench}: {} runs, each in a fresh process", self.plan.runs);
70	            println!();
71	            if !show_report {
72	                println!("{}", run_header());
73	            }
74	        }
75	        let mut means = Vec::with_capacity(self.plan.runs as usize);
76	        for run in 1..=self.plan.runs {
77	            if self.spawned > 0 && self.plan.run_sleep_s.1 > 0.0 {
78	                let s = self.dither.span_s(self.plan.run_sleep_s);
79	                std::thread::sleep(std::time::Duration::from_secs_f64(s));
80	            }
81	            let n = self.spawned;
82	            self.spawned += 1;
83	            let result = self.plan.scratch.join(format!("run-{n}.jsonl"));
84	            let spec = Spec::new(bench, run, cfg, record, result.clone());
85	            let spec_path = self.plan.scratch.join(format!("run-{n}.json"));
86	            child::spawn(
87	                self.plan.exe,
88	                &spec_path,
89	                &spec,
90	                show_report,
91	                self.plan.verbose,
92	            )?;
93	            let summaries = record::read_summaries(&result)?;
94	            if several {
95	                if show_report {
96	                    println!("{}", run_header());
97	                }
98	                if summaries.is_empty() {
99	                    println!("{run:>5}  no record: a probe bench records nothing");
100	                }
101	                for s in &summaries {
102	                    println!("{}", run_line(run, s, self.plan.decimals));
103	                }
104	            }
105	            means.extend(summaries.iter().map(|s| s.mean_ns));
106	        }
107	        if several {
108	            println!();
109	            print_summary_rows(&summary_rows(&means, self.plan.decimals));
110	            println!();
111	        }
112	        Ok(())
113	    }
114	}
115	
116	/// The run table's header, over [`run_line`]'s columns.
117	fn run_header() -> String {
118	    format!(
119	        "{:>5}  {:>8}  {:>14}  {:>14}  {:>14}",
120	        "run", "pid", "mean", "CI95 blocks", "LSC blocks"
121	    )
122	}
123	
124	/// One run's line: its index, the child's pid, the run's mean, and its within-process CI95 and
125	/// LSC, a withheld claim printing `-`.
126	fn run_line(run: u64, s: &RunSummary, decimals: usize) -> String {
127	    let claim = |v: Option<f64>| match v {
128	        Some(x) => format!("{} ns", fmt_claim(x, decimals.max(1))),
129	        None => "-".to_string(),
130	    };
131	    format!(
132	        "{run:>5}  {:>8}  {:>14}  {:>14}  {:>14}",
133	        s.pid,
134	        format!("{} ns", fmt_commas_f64(s.mean_ns, decimals)),
135	        claim(s.block_ci95_ns),
136	        claim(s.block_lsc_ns),
137	    )
138	}
139	
140	/// A bench's summary rows over its run means: the plain mean, the run-to-run stdev, and the CI95
141	/// and LSC across runs, each `-` below two runs, where no spread exists.
142	fn summary_rows(means: &[f64], decimals: usize) -> Vec<(String, String)> {
143	    let dash = || "-".to_string();
144	    let (mean, stdev, ci95, lsc) = match Series::of(means) {
145	        Some(s) => (
146	            fmt_commas_f64(s.mean, decimals),
147	            fmt_commas_f64(s.stdev, decimals),
148	            fmt_claim(s.ci95(), decimals.max(1)),
149	            fmt_claim(s.lsc(), decimals.max(1)),
150	        ),
151	        None => (dash(), dash(), dash(), dash()),
152	    };
153	    vec![
154	        ("mean".to_string(), mean),
155	        ("stdev".to_string(), stdev),
156	        ("CI95 runs".to_string(), ci95),
157	        ("LSC runs".to_string(), lsc),
158	    ]
159	}
160	
161	#[cfg(test)]
162	mod tests {
163	    use super::*;
164	
165	    #[test]
166	    fn summary_rows_come_from_the_run_means() {
167	        let rows = summary_rows(&[10.0, 12.0, 14.0], 1);
168	        assert_eq!(rows[0], ("mean".to_string(), "12.0".to_string()));
169	        assert_eq!(rows[1], ("stdev".to_string(), "2.0".to_string()));
170	        // t(0.975, 2) * 2 / sqrt(3) and t(0.975, 4) * 2 * sqrt(2/3).
171	        assert_eq!(rows[2], ("CI95 runs".to_string(), "5.0".to_string()));
172	        assert_eq!(rows[3], ("LSC runs".to_string(), "4.5".to_string()));
173	    }
174	
175	    #[test]
176	    fn one_run_has_no_spread() {
177	        let rows = summary_rows(&[10.0], 1);
178	        assert!(rows.iter().all(|(_, v)| v == "-"), "{rows:?}");
179	    }
180	
181	    #[test]
182	    fn a_run_line_lines_up_under_its_header() {
183	        let s = RunSummary {
184	            bench: "min-now".to_string(),
185	            pid: 4242,
186	            mean_ns: 24.64,
187	            block_ci95_ns: Some(0.04),
188	            block_lsc_ns: None,
189	        };
190	        let line = run_line(3, &s, 1);
191	        assert_eq!(line.len(), run_header().len());
192	        assert!(line.contains("24.6 ns"), "{line}");
193	        assert!(line.contains("0.04 ns"), "{line}");
194	        assert!(line.trim_end().ends_with('-'), "{line}");
195	    }
196	}
